use crate::{
    client::{print, Client},
    id,
};
use den_core::*;
use reqwest::Method;
use std::{
    io::{Read, Seek, SeekFrom},
    path::Path,
    time::Duration,
};
use tungstenite::{client::IntoClientRequest, Message as Frame};

pub fn tail(c: &Client, channel: Option<String>) -> anyhow::Result<()> {
    let token = c
        .token
        .as_ref()
        .ok_or_else(|| anyhow::anyhow!("Login or set DEN_TOKEN first"))?;
    if let Some(channel) = &channel {
        let _: Channel = c.get(&format!("/channels/{}", id(channel)?))?;
    }
    let url = format!("{}/ws", c.url.replacen("http", "ws", 1));
    let mut delay = 1;
    let mut auth_headers = tungstenite::http::HeaderMap::new();
    auth_headers.insert("Authorization", format!("Bearer {token}").parse()?);
    loop {
        let mut request = url.as_str().into_client_request()?;
        request.headers_mut().extend(auth_headers.drain());
        match tungstenite::connect(request) {
            Ok((mut socket, _)) => {
                // Detect a half-open connection even when no chat events arrive.
                match socket.get_mut() {
                    tungstenite::stream::MaybeTlsStream::Plain(tcp) => {
                        tcp.set_read_timeout(Some(Duration::from_secs(50)))?;
                        tcp.set_write_timeout(Some(Duration::from_secs(10)))?;
                    }
                    tungstenite::stream::MaybeTlsStream::Rustls(tls) => {
                        tls.sock.set_read_timeout(Some(Duration::from_secs(50)))?;
                        tls.sock.set_write_timeout(Some(Duration::from_secs(10)))?;
                    }
                    _ => {}
                }
                delay = 1;
                loop {
                    match socket.read() {
                        Ok(Frame::Text(text)) => {
                            let event: Event = serde_json::from_str(&text)?;
                            if let Event::Resync { reason } = &event {
                                eprintln!("Gap: {reason}. Run den read to refresh; events are not replayed.");
                            }
                            let event_channel = match &event {
                                Event::MessageCreated(m) | Event::MessageEdited(m) => {
                                    Some(&m.channel_id)
                                }
                                Event::MessageDeleted { channel_id, .. }
                                | Event::ObjectPatched { channel_id, .. }
                                | Event::ObjectPresence { channel_id, .. }
                                | Event::Typing { channel_id, .. } => Some(channel_id),
                                _ => None,
                            };
                            if channel.is_none()
                                || event_channel.is_none()
                                || event_channel == channel.as_ref()
                            {
                                print(&event)?;
                            }
                        }
                        Ok(Frame::Ping(bytes)) => {
                            if socket.send(Frame::Pong(bytes)).is_err() {
                                break;
                            }
                        }
                        Ok(Frame::Close(_)) | Err(_) => break,
                        _ => {}
                    }
                }
            }
            Err(tungstenite::Error::Http(response))
                if response.status().as_u16() == 403 =>
            {
                anyhow::bail!("Authentication rejected; log in again")
            }
            Err(_) => {}
        }
        eprintln!("Connection lost; events may be missing. Reconnecting in {delay}s.");
        std::thread::sleep(Duration::from_secs(delay));
        delay = (delay * 2).min(30);
    }
}
pub fn upload(
    c: &Client,
    channel: &str,
    path: &Path,
    resume: Option<String>,
    content_type: Option<String>,
) -> anyhow::Result<()> {
    let mut file = std::fs::File::open(path)?;
    let size = i64::try_from(file.metadata()?.len())?;
    let filename = path
        .file_name()
        .and_then(|v| v.to_str())
        .ok_or_else(|| anyhow::anyhow!("Invalid filename"))?
        .to_string();
    let mime = content_type.unwrap_or_else(|| {
        match path
            .extension()
            .and_then(|v| v.to_str())
            .unwrap_or("")
            .to_ascii_lowercase()
            .as_str()
        {
            "mp4" | "m4v" => "video/mp4",
            "mov" => "video/quicktime",
            "webm" => "video/webm",
            "mp3" => "audio/mpeg",
            "m4a" => "audio/mp4",
            "ogg" => "audio/ogg",
            "wav" => "audio/wav",
            "png" => "image/png",
            "jpg" | "jpeg" => "image/jpeg",
            "gif" => "image/gif",
            "webp" => "image/webp",
            _ => "application/octet-stream",
        }
        .into()
    });
    let mut upload: Upload = if let Some(resume) = resume {
        c.get(&format!("/uploads/{}", id(&resume)?))?
    } else {
        c.send(
            Method::POST,
            "/uploads",
            &BeginUpload {
                channel_id: channel.into(),
                filename: filename.clone(),
                content_type: mime,
                size,
            },
        )?
    };
    anyhow::ensure!(
        upload.channel_id == channel && upload.size == size && upload.filename == filename,
        "Resume metadata does not match this file/channel; use the original unchanged file"
    );
    eprintln!(
        "Upload {}: resume with den upload {} {:?} --resume {}",
        upload.id, channel, path, upload.id
    );
    let mut buffer = vec![0u8; 4 * 1024 * 1024];
    while upload.offset < size {
        file.seek(SeekFrom::Start(upload.offset as u64))?;
        let count = file.read(&mut buffer)?;
        anyhow::ensure!(count > 0, "File changed during upload");
        upload = Client::decode(
            c.request(Method::PATCH, &format!("/uploads/{}", upload.id))
                .header("Upload-Offset", upload.offset)
                .header("Content-Type", "application/octet-stream")
                .body(buffer[..count].to_vec())
                .send()?,
        )?;
        eprintln!("{} / {} bytes", upload.offset, size);
    }
    let result: Upload = c.send(
        Method::POST,
        &format!("/uploads/{}/complete", upload.id),
        &serde_json::json!({}),
    )?;
    print(&result)
}

"""Local-only Den CLI incident reproduction. Requires supplied arena Python runtime."""
import argparse, json, logging, os, subprocess, tempfile, threading, time
from pathlib import Path
from http import HTTPStatus
from websockets.sync.server import serve

TOKEN='synthetic-arena-token'
CID='00000000000000000000000100'
OTHER='00000000000000000000000200'

def event(i, channel=CID):
    return {'type':'message_created','id':f'{i:026d}','channel_id':channel,'author_id':'00000000000000000000000300','content':f'event {i}','reply_to':None,'created_at':'2026-09-14T00:00:00Z','edited_at':None,'attachments':[],'objects':[],'reactions':[],'mention_ids':[]}

def exercise(binary, *, mode='reconnect', channel=False, deadline=8):
    attempts=[]; accepted=[]; pong=[]; request_paths=[]
    def process(connection, request):
        request_paths.append(request.path)
        if request.path.startswith('/channels/'):
            value={'id':CID,'name':'general','kind':'text','category_id':None,'position':0,'member_ids':[]}
            response=connection.respond(HTTPStatus.OK,json.dumps(value));response.headers['Content-Type']='application/json';return response
        auth=request.headers.get('Authorization')=='Bearer '+TOKEN
        attempts.append(auth); number=len(attempts)
        if mode in ['401','403']:
            return connection.respond(int(mode),'Credentials rejected\n')
        if mode=='transient' and number==1:
            return connection.respond(HTTPStatus.SERVICE_UNAVAILABLE,'Retry later\n')
        if not auth or number>=3:
            return connection.respond(HTTPStatus.UNAUTHORIZED,'Credentials rejected\n')
        return None
    def handler(ws):
        number=len(attempts); accepted.append(number)
        ws.send(json.dumps({'type':'resync','reason':'connected; refresh history'}))
        if mode=='filter':
            ws.send(json.dumps(event(90,OTHER)))
            ws.send(json.dumps({'type':'presence','user_id':'00000000000000000000000300','online':True}))
        waiter=ws.ping(b'arena-ping');pong.append(waiter.wait(2))
        ws.send(json.dumps(event(number)))
        ws.close()
    logging.getLogger('websockets.server').setLevel(logging.CRITICAL)
    with serve(handler,'127.0.0.1',0,process_request=process,ping_interval=None,close_timeout=.3) as server:
        thread=threading.Thread(target=server.serve_forever,daemon=True);thread.start()
        env={k:v for k,v in os.environ.items() if not k.startswith('DEN_')}
        with tempfile.TemporaryDirectory(prefix='arena-tail-') as tmp:
            cmd=[str(binary),'--url',f'http://127.0.0.1:{server.socket.getsockname()[1]}','--token',TOKEN,'--config',str(Path(tmp)/'credentials.json'),'tail']
            if channel:cmd.append(CID)
            start=time.monotonic();p=subprocess.Popen(cmd,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,env=env)
            timeout=False
            try: stdout,stderr=p.communicate(timeout=deadline)
            except subprocess.TimeoutExpired:
                timeout=True;p.kill();stdout,stderr=p.communicate()
        server.shutdown();thread.join(timeout=2)
    try:events=[json.loads(line) for line in stdout.splitlines()]
    except ValueError:events=None
    ids=[e['id'] for e in events or [] if e['type']=='message_created']
    expected=[] if mode in ['401','403'] else ([f'{2:026d}'] if mode=='transient' else [f'{1:026d}',f'{2:026d}'])
    checks={'exits_on_auth_rejection':not timeout and p.returncode!=0,
            'one_connection_on_initial_rejection':len(attempts)==1 if mode in ['401','403'] else True,
            'auth_on_every_connection':all(attempts),
            'expected_events_once':ids==expected,
            'json_only_stdout':events is not None,
            'ping_response':all(pong),
            'gap_diagnostics':('Gap:' in stderr and 'Connection lost' in stderr) if accepted else True,
            'global_resync_events':sum(e['type']=='resync' for e in events or [])==len(accepted),
            'global_presence_events':sum(e['type']=='presence' for e in events or [])==len(accepted) if mode=='filter' else True}
    return {'passed':all(checks.values()),'checks':checks,'elapsed_seconds':round(time.monotonic()-start,2),'attempts_authenticated':attempts,'accepted_connections':accepted,'stdout':stdout,'stderr':stderr,'returncode':p.returncode,'timed_out':timeout,'requests':request_paths}

if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('binary',type=Path);args=parser.parse_args()
    result=exercise(args.binary.resolve());print(json.dumps(result,indent=2));raise SystemExit(0 if result['passed'] else 1)

mod canvas;
mod client;
mod hosts;
mod stream;
use anyhow::Context;
use clap::{Parser, Subcommand};
use client::{print, Client};
use den_core::*;
use reqwest::Method;
use std::path::PathBuf;

#[derive(Parser)]
#[command(
    name = "den",
    version,
    about = "Talk to a Den server; command results are JSON"
)]
struct Cli {
    #[arg(
        long,
        env = "DEN_URL",
        default_value = "http://127.0.0.1:7000",
        global = true
    )]
    url: String,
    #[arg(long, env = "DEN_TOKEN", global = true, hide_env_values = true)]
    token: Option<String>,
    #[arg(long, env = "DEN_CONFIG", global = true)]
    config: Option<PathBuf>,
    #[command(subcommand)]
    cmd: Cmd,
}
#[derive(Subcommand)]
enum Cmd {
    Health,
    #[command(subcommand)]
    Host(hosts::HostCmd),
    #[command(subcommand)]
    Access(hosts::AccessCmd),
    #[command(subcommand)]
    Terminal(hosts::TerminalCmd),
    #[command(subcommand)]
    Canvas(canvas::Cmd),
    /// Claim a new local instance using its one-time key file.
    Init {
        username: String,
        #[arg(long, default_value = "data/bootstrap.key")]
        bootstrap_file: PathBuf,
        #[arg(long)]
        password_stdin: bool,
    },
    Login {
        username: String,
        #[arg(long)]
        password_stdin: bool,
    },
    Register {
        username: String,
        #[arg(long, env = "DEN_INVITE", hide_env_values = true)]
        invite: String,
        #[arg(long)]
        password_stdin: bool,
    },
    Logout,
    Me,
    Users,
    Channels,
    #[command(subcommand)]
    Channel(ChannelCmd),
    #[command(subcommand)]
    Category(CategoryCmd),
    #[command(subcommand)]
    Invite(InviteCmd),
    /// Create or reopen a DM with the exact member set, including yourself.
    Dm {
        /// User ULIDs or @usernames. Your own user is included automatically.
        members: Vec<String>,
    },
    Send {
        /// Channel ULID, text channel name (general or #general), or @username for a DM.
        channel: String,
        text: String,
        #[arg(long)]
        reply_to: Option<String>,
        #[arg(long = "upload")]
        uploads: Vec<String>,
    },
    Read {
        /// Channel ULID, text channel name (general or #general), or @username for a DM.
        channel: String,
        #[arg(long)]
        before: Option<String>,
        #[arg(long)]
        after: Option<String>,
        #[arg(long, default_value_t = 50)]
        limit: u32,
    },
    Edit {
        message: String,
        text: String,
    },
    Delete {
        message: String,
    },
    /// Print events as JSON lines; reconnects report gaps requiring a fresh read.
    Tail {
        /// Channel ULID, text channel name (general or #general), or @username for a DM.
        channel: Option<String>,
    },
    /// Upload a file; use the printed ID with --resume after interruption.
    Upload {
        /// Channel ULID, text channel name (general or #general), or @username for a DM.
        channel: String,
        file: PathBuf,
        #[arg(long)]
        resume: Option<String>,
        #[arg(long)]
        content_type: Option<String>,
    },
    #[command(subcommand)]
    Token(TokenCmd),
    #[command(subcommand)]
    Bot(BotCmd),
}
#[derive(Subcommand)]
enum ChannelCmd {
    Create {
        name: String,
        #[arg(long)]
        category: Option<String>,
        #[arg(long, default_value_t = 0)]
        position: i64,
    },
    Update {
        /// Channel ULID, text channel name (general or #general), or @username for a DM.
        #[arg(value_name = "CHANNEL")]
        id: String,
        name: String,
        #[arg(long)]
        category: Option<String>,
        #[arg(long, default_value_t = 0)]
        position: i64,
    },
    Delete {
        /// Channel ULID, text channel name (general or #general), or @username for a DM.
        #[arg(value_name = "CHANNEL")]
        id: String,
    },
}
#[derive(Subcommand)]
enum CategoryCmd {
    List,
    Create {
        name: String,
        #[arg(long, default_value_t = 0)]
        position: i64,
    },
    Update {
        id: String,
        name: String,
        #[arg(long, default_value_t = 0)]
        position: i64,
    },
    Delete {
        id: String,
    },
}
#[derive(Subcommand)]
enum InviteCmd {
    Create {
        #[arg(long, default_value_t = 1)]
        uses: u32,
        #[arg(long, default_value_t = 24)]
        hours: u32,
    },
    Revoke {
        id: String,
    },
}
#[derive(Subcommand)]
enum TokenCmd {
    Create {
        name: String,
        #[arg(long)]
        user: Option<String>,
    },
    List,
    Revoke {
        id: String,
    },
}
#[derive(Subcommand)]
enum BotCmd {
    Create {
        username: String,
        #[arg(long)]
        display_name: Option<String>,
    },
}
fn password(stdin: bool) -> anyhow::Result<String> {
    if let Ok(value) = std::env::var("DEN_PASSWORD") {
        return Ok(value);
    }
    anyhow::ensure!(stdin, "Set DEN_PASSWORD or pass --password-stdin");
    let mut value = String::new();
    std::io::stdin().read_line(&mut value)?;
    Ok(value.trim_end_matches(['\r', '\n']).to_string())
}
fn id(value: &str) -> anyhow::Result<&str> {
    anyhow::ensure!(
        value.len() == 26 && value.bytes().all(|b| b.is_ascii_alphanumeric()),
        "Expected a ULID"
    );
    Ok(value)
}
fn main() -> anyhow::Result<()> {
    let args = Cli::parse();
    let mut c = Client::new(args.url, args.token, args.config)?;
    match args.cmd {
        Cmd::Canvas(cmd) => canvas::run(&c, cmd)?,
        Cmd::Host(cmd) => hosts::host(&c, cmd)?,
        Cmd::Access(cmd) => hosts::access(&c, cmd)?,
        Cmd::Terminal(cmd) => hosts::terminal(&c, cmd)?,
        Cmd::Health => print(&c.get::<Health>("/health")?)?,
        Cmd::Init {
            username,
            bootstrap_file,
            password_stdin,
        } => {
            let session: Session = c.send(
                Method::POST,
                "/auth/init",
                &Bootstrap {
                    username,
                    password: password(password_stdin)?,
                    bootstrap_token: std::fs::read_to_string(bootstrap_file)
                        .context("Read the bootstrap key on the server machine")?,
                },
            )?;
            print(&session.user)?;
            c.save(session)?;
        }
        Cmd::Login {
            username,
            password_stdin,
        } => {
            let session: Session = c.send(
                Method::POST,
                "/auth/login",
                &Login {
                    username,
                    password: password(password_stdin)?,
                },
            )?;
            print(&session.user)?;
            c.save(session)?;
        }
        Cmd::Register {
            username,
            invite,
            password_stdin,
        } => {
            let session: Session = c.send(
                Method::POST,
                "/auth/register",
                &Register {
                    username,
                    password: password(password_stdin)?,
                    invite,
                },
            )?;
            print(&session.user)?;
            c.save(session)?;
        }
        Cmd::Logout => {
            c.empty(Method::POST, "/auth/logout")?;
            c.forget()?;
        }
        Cmd::Me => print(&c.get::<User>("/users/me")?)?,
        Cmd::Users => print(&c.get::<Vec<User>>("/users")?)?,
        Cmd::Channels => print(&c.get::<Vec<Channel>>("/channels")?)?,
        Cmd::Channel(v) => match v {
            ChannelCmd::Create {
                name,
                category,
                position,
            } => print(&c.send::<Channel>(
                Method::POST,
                "/channels",
                &SaveChannel {
                    name,
                    category_id: category,
                    position,
                },
            )?)?,
            ChannelCmd::Update {
                id: cid,
                name,
                category,
                position,
            } => print(&c.send::<Channel>(
                Method::PUT,
                &format!("/channels/{}", c.resolve_channel(&cid)?),
                &SaveChannel {
                    name,
                    category_id: category,
                    position,
                },
            )?)?,
            ChannelCmd::Delete { id: cid } => c.empty(
                Method::DELETE,
                &format!("/channels/{}", c.resolve_channel(&cid)?),
            )?,
        },
        Cmd::Category(v) => match v {
            CategoryCmd::List => print(&c.get::<Vec<Category>>("/categories")?)?,
            CategoryCmd::Create { name, position } => print(&c.send::<Category>(
                Method::POST,
                "/categories",
                &SaveCategory { name, position },
            )?)?,
            CategoryCmd::Update {
                id: cid,
                name,
                position,
            } => print(&c.send::<Category>(
                Method::PUT,
                &format!("/categories/{}", id(&cid)?),
                &SaveCategory { name, position },
            )?)?,
            CategoryCmd::Delete { id: cid } => {
                c.empty(Method::DELETE, &format!("/categories/{}", id(&cid)?))?
            }
        },
        Cmd::Invite(v) => match v {
            InviteCmd::Create { uses, hours } => print(&c.send::<Invite>(
                Method::POST,
                "/invites",
                &CreateInvite {
                    uses,
                    expires_in_hours: hours,
                },
            )?)?,
            InviteCmd::Revoke { id: cid } => {
                c.empty(Method::DELETE, &format!("/invites/{}", id(&cid)?))?
            }
        },
        Cmd::Dm { members } => print(&c.dm(&members)?)?,
        Cmd::Send {
            channel,
            text,
            reply_to,
            uploads,
        } => print(&c.send::<Message>(
            Method::POST,
            &format!("/channels/{}/messages", c.resolve_channel(&channel)?),
            &CreateMessage {
                content: text,
                reply_to,
                upload_ids: uploads,
            },
        )?)?,
        Cmd::Read {
            channel,
            before,
            after,
            limit,
        } => {
            let mut path = format!(
                "/channels/{}/messages?limit={limit}",
                c.resolve_channel(&channel)?
            );
            if let Some(v) = before {
                path.push_str(&format!("&before={}", id(&v)?));
            }
            if let Some(v) = after {
                path.push_str(&format!("&after={}", id(&v)?));
            }
            print(&c.get::<Vec<Message>>(&path)?)?;
        }
        Cmd::Edit { message, text } => print(&c.send::<Message>(
            Method::PATCH,
            &format!("/messages/{}", id(&message)?),
            &EditMessage { content: text },
        )?)?,
        Cmd::Delete { message } => {
            c.empty(Method::DELETE, &format!("/messages/{}", id(&message)?))?
        }
        Cmd::Tail { channel } => {
            let channel = channel
                .as_deref()
                .map(|v| c.resolve_channel(v))
                .transpose()?;
            stream::tail(&c, channel)?;
        }
        Cmd::Upload {
            channel,
            file,
            resume,
            content_type,
        } => stream::upload(
            &c,
            &c.resolve_channel(&channel)?,
            &file,
            resume,
            content_type,
        )?,
        Cmd::Token(v) => match v {
            TokenCmd::Create { name, user } => print(&c.send::<TokenSecret>(
                Method::POST,
                "/tokens",
                &CreateToken {
                    name,
                    user_id: user,
                },
            )?)?,
            TokenCmd::List => print(&c.get::<Vec<Token>>("/tokens")?)?,
            TokenCmd::Revoke { id: tid } => {
                c.empty(Method::DELETE, &format!("/tokens/{}", id(&tid)?))?
            }
        },
        Cmd::Bot(BotCmd::Create {
            username,
            display_name,
        }) => print(&c.send::<BotCreated>(
            Method::POST,
            "/bots",
            &CreateBot {
                display_name: display_name.unwrap_or_else(|| username.clone()),
                username,
            },
        )?)?,
    }
    Ok(())
}

